#!/usr/bin/env python3
"""Supplement the standard award API batch with actual funded OTIDV schemas.
Do not conflate OtherTransactionIDV prototypes with zero-funded FAR IDV parents.
Keep aggregate/action-sum discrepancies instead of selecting a convenient total.
"""
import csv,json,pathlib
P=pathlib.Path(__file__).resolve().parents[1]
if __name__=='__main__':
 rows=list(csv.DictReader((P/'evidence/live-candidate-disposition.csv').open()));byid={r['piid']:r for r in rows};targets=[]
 for n in ['ota-resolution-review.json','ota-keyword-followup-records.json']:targets+=json.loads((P/'evidence'/n).read_text())['targets']
 for t in targets:
  piid=t['piid'];existing=byid.get(piid);r=dict(existing) if existing else {k:'' for k in rows[0]};first=t['actions'][0];dates=sorted(a['signed_date'][:10] for a in t['actions'])
  normative='CODORD' in t['program_lead']
  r.update(piid=piid,award_key=first['primary_identity'],recipient=first['recipient'],technical_title_or_description=t['program_lead'],primary_award_description=' | '.join(dict.fromkeys(a['description'] for a in t['actions'])),classification='A-enabling;C' if normative else 'C;A-semantic-contribution',scope_tier='military_rule_reasoning_enabling; weapons benchmark not established' if normative else 'technical_assurance_with_ROE_semantic_goal; normative validation not established',disposition='Resolved via primary OtherTransactionIDV schema; public normative/assurance research, not fielded legal governor',technical_review_depth='Exact primary FPDS XML schema and official program scope; task/deployment limits retained',technical_source_urls='https://www.darpa.mil/research/programs/codord' if normative else 'https://www.darpa.mil/research/programs/transfer-from-imprecise',in_selected_case_register=False,in_selected_case_money_sum=False,net_obligations_usd=t['action_obligation_sum_usd'] if t['visible_actions_reconcile_feed_aggregate'] else '',source_url=t['pages'][0]['url'],financial_verification='FPDS visible actions sum exactly to feed aggregate; no USAspending match' if t['visible_actions_reconcile_feed_aggregate'] else 'UNRESOLVED: visible action sum differs from feed aggregate; excluded from reconciled totals',date_signed=min(dates),performance_start=min(a['effective_date'][:10] for a in t['actions'] if a['effective_date']),current_end=t['latest_visible_current_end'][:10],potential_end=t['latest_visible_potential_end'][:10],record_currentness_status='record_period_overlaps_cutoff' if t['record_period_overlaps_cutoff'] else 'record_period_ended; potential options not current performance',last_public_action_date=t['latest_signed_date'][:10],last_positive_obligation_date=t['last_positive_obligation_date'][:10],reporting_limit='Public DoD OT release/reporting bounded; complete returned feed is not all real-world actions',termination_completion_evidence='No termination decision established; preserve current versus potential dates',independent_activity_evidence='Official program lists research outputs; no actual weapons-governor deployment established')
  r['previous_standard_API_resolution']='No exact USAspending detail in original batch; schema gap now resolved' if existing else 'Added by targeted primary OT keyword/identity follow-up'
  r['funding_instrument_schema']='FPDS OtherTransactionIDV funded prototype, not a FAR parent-IDV ceiling'
  r['visible_ot_action_obligations_usd']=t['action_obligation_sum_usd'];r['ot_feed_aggregate_obligations_usd']=t['feed_aggregate_obligations_usd'];r['ot_aggregate_minus_actions_usd']=t['aggregate_minus_visible_actions_usd'];r['ot_visible_actions_reconcile']=t['visible_actions_reconcile_feed_aggregate'];r['ot_action_count']=t['visible_action_count'];r['source_response_sha256']=t['pages'][0]['sha256']
  byid[piid]=r
 out=list(byid.values());fields=list(dict.fromkeys(k for r in out for k in r))
 with (P/'evidence/combined-live-inventory.csv').open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(out)
 note={'original_standard_API_candidates':len(rows),'standard_API_details':105,'OT_schema_records':len(targets),'prior_unresolved_identities_now_resolved':2,'additional_OT_identities':len(targets)-2,'combined_unique_instrument_identities':len(out),'OT_visible_actions':sum(t['visible_action_count'] for t in targets),'OT_exact_aggregate_reconciliations':sum(t['visible_actions_reconcile_feed_aggregate'] for t in targets),'OT_unresolved_money_discrepancies':sum(not t['visible_actions_reconcile_feed_aggregate'] for t in targets),'OT_money_not_added_to_selected_case_totals':True,'scope':'Instrument identities, not program count. Primary feeds resolve earlier schema omissions; each money presentation and unresolved discrepancy remains separate.'}
 (P/'audit/combined-live-inventory-accounting.json').write_text(json.dumps(note,indent=2)+'\n');print(json.dumps(note,indent=2))
